safes.solution:
def count_gears(sizes):
    counts = {}
    for s in sizes:
        counts[s] = counts.get(s, 0) + 1
    return counts

def chain_length(chain):
    if not chain:
        return 0
    return 1 + chain_length(chain[1:])

